import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))

        max_ops = 0
        current_n = n

        while current_n > 0:
            max_ops += (1 << (current_n - 1))
            current_n -= 1

        if k <= max_ops:
            remaining_k = k
            side_log = n
            while side_log > 0:
                needed = 1 << (side_log - 1)
                if remaining_k <= needed:
                    break
                remaining_k -= needed
                side_log -= 1
            results.append(f"YES {side_log}")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
